import '../styles/cart.css';
import {useState} from 'react';

function Cart({cartItems, setCartItems}) {
    const item1 = 15;
    const item2 = 20;

    let total = 0;
    for (let item of cartItems) {
        total += item.prix * item.quantity
    }

    // const [quantite1, setQuantite1] = useState(0);
    // const [quantite2, setQuantite2] = useState(0);
    return (
        <div className="cart">
            <h1>Cart</h1>
            {cartItems.map((item) => (
                <div className="cart-item">
                    <p>{item.nom} : </p>
                    <p>{item.prix}€</p>
                    <p>QTE : {item.quantity}</p>
                </div>
            ))}
            <div className="cart-item">
                {/* <p>Item 1: {item1}€</p> */}
                {/* <button onClick={() => setQuantite1(quantite1 + 1)}>+</button> */}
                {/* <p>QTE : {quantite1}</p> */}
            </div>
            <div className="cart-item">
               {/* <p>Item 2: {item2}€</p> */}
                {/* <button onClick={() => setQuantite2(quantite2 + 1)}>+</button> */}
                {/* <p>QTE : {quantite2}</p> */}
            </div>
            <div className="cart-total">
                <p><b>Total:</b>{total}€</p>
                
                <button className="button" onClick={() => {setCartItems([])}}>Vider le panier</button>
            </div>
        </div>
    );
}
export default Cart;
